274	    /**
275	     * Builds the owner's customer code as {@code '<REGION>-<HASH8>'}, where {@code REGION} is the
276	     * region derived from the owner's postcode (falling back to its city, else {@code 'UNKNOWN'}) via
277	     * {@link OwnerMapper#toRegion}, and {@code HASH8} is the first 8 upper-case hex characters of the
278	     * SHA-256 digest of {@code normalizedTelephone + lastName} (e.g. {@code NSW-1A2B3C4D}). The code
279	     * carries no sequence number: it is a deterministic function of the owner's region and identity.
280	     *
281	     * @param owner the owner being created, with its region-determining postcode and city populated
282	     * @param normalizedTelephone the owner's normalized (E.164) telephone, hashed with the last name
283	     * @return the region-and-hash customer code for the owner being created
284	     */
285	    private String buildCustomerCode(Owner owner, String normalizedTelephone) {
286	        String region = ownerMapper.toRegion(owner);
287	        String hash8 = sha256Hex8(normalizedTelephone + owner.getLastName());
288	        return region + "-" + hash8;
289	    }
290	
291	    /**
292	     * Returns the first 8 upper-case hex characters of the SHA-256 digest of {@code value}'s UTF-8
293	     * bytes. Deterministic, so the same input always yields the same 8-character hash.
294	     */
295	    private static String sha256Hex8(String value) {
296	        try {
297	            byte[] digest = MessageDigest.getInstance("SHA-256")
298	                .digest(value.getBytes(StandardCharsets.UTF_8));
299	            StringBuilder sb = new StringBuilder();
300	            for (byte b : digest) {
301	                sb.append(String.format("%02X", b));
302	            }
303	            return sb.substring(0, 8);
304	        }
305	        catch (NoSuchAlgorithmException e) {
306	            throw new IllegalStateException("SHA-256 not available", e);
307	        }
308	    }
309	
310	    /**
311	     * Counts the existing owners (those already persisted before this create) whose first and last
312	     * names both match the incoming owner's, compared case-insensitively. This snapshot is stored on
313	     * the new owner as its {@code namesakeCount} and echoed back on reads.
314	     *
315	     * @param firstName the incoming owner's first name (already validated non-blank)
316	     * @param lastName the incoming owner's last name (already validated non-blank)
317	     * @return the number of existing namesakes sharing both names case-insensitively
318	     */
319	    private int countNamesakes(String firstName, String lastName) {
320	        return (int) this.clinicService.findAllOwners().stream()
321	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
322	                && lastName.equalsIgnoreCase(existing.getLastName()))
323	            .count();
324	    }
325	
326	    /**
327	     * Records {@code fieldName} as missing when {@code value} is {@code null} or blank (empty or
328	     * whitespace-only), so the caller can reject the request listing every offending field.
329	     */
330	    private static void requireNonBlank(List<String> missingFields, String fieldName, String value) {
331	        if (value == null || value.isBlank()) {
332	            missingFields.add(fieldName);
333	        }
334	    }
335	
336	    /**
337	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. When the
338	     * value carries a leading {@code '+'} its country code is kept; otherwise a {@code '+61'} country
339	     * code is assumed and a single leading {@code '0'} is dropped from the national digits. The result
340	     * must be a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} becomes
341	     * {@code "+61412345678"}.
342	     *
343	     * @param telephone the raw telephone value from the request
344	     * @return the normalized E.164 telephone number (a {@code '+'} followed by 8 to 15 digits)
345	     * @throws InvalidFieldValueException if the value cannot form a valid E.164 number
346	     */
347	    private static String normalizeTelephone(String telephone) {
348	        String e164 = toE164(telephone);
349	        if (e164 == null) {
350	            throw new InvalidFieldValueException("telephone",
351	                "Telephone must be a valid E.164 number ('+' followed by 8 to 15 digits)");
352	        }
353	        return e164;
354	    }
355	
356	    /**
357	     * Converts a raw telephone value to E.164 form, or returns {@code null} when it cannot form a
358	     * valid E.164 number. Used both to normalize incoming values and to compare against existing
359	     * owners' stored numbers when detecting duplicates.
360	     */
361	    private static String toE164(String telephone) {
362	        if (telephone == null) {
363	            return null;
364	        }
365	        String cleaned = telephone.trim().replaceAll("[\\s\\-()]", "");
366	        String digits;
367	        if (cleaned.startsWith("+")) {
368	            digits = cleaned.substring(1);
369	        } else {
370	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
371	            digits = "61" + national;
372	        }
373	        if (!digits.matches("[0-9]{8,15}")) {
374	            return null;
375	        }
376	        if (!hasValidNationalLength(digits)) {
377	            return null;
378	        }
379	        return "+" + digits;
380	    }
381	
382	    /**
383	     * Checks the national-number length against the country code for the country codes that pin one.
384	     * A {@code '+61'} (Australia) number must carry exactly 9 national digits and a {@code '+1'}
385	     * (NANP) number exactly 10; every other country code is accepted on the general 8-to-15-digit
386	     * rule alone. {@code digits} is the E.164 digit string without the leading {@code '+'}.
387	     */
388	    private static boolean hasValidNationalLength(String digits) {
389	        if (digits.startsWith("61")) {
390	            return digits.length() - 2 == 9;
391	        }
392	        if (digits.startsWith("1")) {
393	            return digits.length() - 1 == 10;
394	        }
395	        return true;
396	    }
397	
398	    /**
399	     * Validates and normalizes an owner's email address. A syntactically valid address is required;
400	     * the value is returned lower-cased so it is stored and echoed back in canonical form.
401	     *
402	     * @param email the raw email value from the request (already known to be non-null)
403	     * @return the lower-cased email to be stored and returned
404	     * @throws InvalidFieldValueException if the value is not a syntactically valid email address
405	     */
406	    private static String normalizeEmail(String email) {
407	        String trimmed = email.trim();
408	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
409	            throw new InvalidFieldValueException("email", "Email must be a syntactically valid address");
410	        }
411	        String canonical = trimmed.toLowerCase(Locale.ROOT);
412	        String domain = canonical.substring(canonical.indexOf('@') + 1);
413	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
414	            throw new InvalidFieldValueException("email", "Email must not use a disposable-domain address");
415	        }
416	        return canonical;
417	    }
418	
419	    /** The maximum number of owners permitted in a single city; the {@code (50 + 1)}th is rejected. */
420	    private static final int MAX_OWNERS_PER_CITY = 50;
421	
422	    /**
423	     * Rejects the request when the owner's city already contains {@link #MAX_OWNERS_PER_CITY} or more
424	     * owners, comparing city names case-insensitively. Callers reach this only once {@code city} has
425	     * been validated non-blank.
426	     *
427	     * @param city the incoming owner's city (already validated non-blank)
428	     * @throws CityAtCapacityException if the city is already at or above its owner capacity
429	     */
430	    /** The maximum number of owners that may be registered in a single day; the {@code (100 + 1)}th is rejected. */
431	    private static final int MAX_OWNERS_PER_DAY = 100;
432	
433	    /**
434	     * Rejects the request when {@link #MAX_OWNERS_PER_DAY} or more owners have already been registered
435	     * on {@code businessDay}, counting existing owners whose {@code registrationDate} equals that date.
436	     * New owners take {@code businessDay} as their {@code registrationDate} (the supplied or defaulted
437	     * date rolled forward to a business day), so this caps the number that may be created per day.
438	     *
439	     * @param businessDay the adjusted business-day registration date of the owner being created
440	     * @throws DailyOwnerLimitException if the daily owner-creation limit has already been reached
441	     */
442	    /**
443	     * The number of owners for a single day beyond which the {@code bulkSignupWarning} flag is
444	     * raised; the warning is true once <em>more than</em> this many owners share a registration date.
445	     */
446	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
447	
448	    /**
449	     * Maps {@code owner} to its DTO and sets the {@code bulkSignupWarning} flag: {@code true} when
450	     * more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for this
451	     * owner's registration date, otherwise {@code false}.
452	     *
453	     * @param owner the owner to map
454	     * @return the owner DTO with its bulk-signup warning flag populated
455	     */
456	    private OwnerDto toOwnerDtoWithBulkWarning(Owner owner) {
457	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
458	        ownerDto.setBulkSignupWarning(exceedsBulkSignupThreshold(owner.getRegistrationDate()));
459	        int points = OwnerMapper.membershipPointsFor(owner, householdSize(owner.getHouseholdId()));
460	        ownerDto.setMembershipPoints(points);
461	        ownerDto.setMembershipLevel(OwnerMapper.membershipLevelFor(points));
462	        return ownerDto;
463	    }
464	
465	    /**
466	     * Returns the number of owners sharing the given {@code householdId} (the household's size),
467	     * counting every existing owner that carries the same {@code householdId}. Returns {@code 0} when
468	     * {@code householdId} is {@code null}, since an owner with no postcode has no household key and so
469	     * no household.
470	     *
471	     * @param householdId the owner's computed household identifier, or {@code null} when absent
472	     * @return the number of owners in the household
473	     */
474	    private int householdSize(String householdId) {
475	        if (householdId == null) {
476	            return 0;
477	        }
478	        return (int) this.clinicService.findAllOwners().stream()
479	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
480	            .count();
481	    }
482	
483	    /**
484	     * Returns whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been
485	     * created on {@code registrationDate}, counting existing owners whose {@code registrationDate}
486	     * equals that date. Returns {@code false} when {@code registrationDate} is {@code null}.
487	     */
488	    private boolean exceedsBulkSignupThreshold(LocalDate registrationDate) {
489	        if (registrationDate == null) {
490	            return false;
491	        }
492	        long registeredThatDay = this.clinicService.findAllOwners().stream()
493	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
494	            .count();
495	        return registeredThatDay > BULK_SIGNUP_WARNING_THRESHOLD;
496	    }
497	
498	    private void requireDailyLimitNotReached(LocalDate businessDay) {
499	        long registeredThatDay = this.clinicService.findAllOwners().stream()
500	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
501	            .count();
502	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
503	            throw new DailyOwnerLimitException(MAX_OWNERS_PER_DAY);
504	        }
505	    }
506	
507	    /**
508	     * Rolls {@code date} forward to a business day: when it falls on a Saturday or Sunday it advances
509	     * to the following Monday; a weekday is returned unchanged. Applied to the effective registration
510	     * date (whether supplied in the request or defaulted to the server date) so a weekend registration
511	     * is recorded on the next business day, and every value derived from the registration date uses the
512	     * adjusted date.
513	     *
514	     * @param date the effective registration date (supplied or defaulted), never {@code null}
515	     * @return the same date, or the next Monday when {@code date} is a weekend
516	     */
517	    private static LocalDate toBusinessDay(LocalDate date) {
518	        DayOfWeek day = date.getDayOfWeek();
519	        if (day == DayOfWeek.SATURDAY) {
520	            return date.plusDays(2);
521	        }
522	        if (day == DayOfWeek.SUNDAY) {
523	            return date.plusDays(1);
524	        }
525	        return date;
526	    }
527	
528	    /** Matches a well-formed postcode: exactly four decimal digits. */
529	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
530	
531	    /**
532	     * Fixed region-to-postcode range table: each region admits an inclusive 4-digit range
533	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). Regions are derived
534	     * from the owner's city via {@link OwnerMapper#CITY_REGION}; a city with no known region is not
535	     * present here and accepts any well-formed postcode.
536	     */
537	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
538	        "NSW", new int[] {2000, 2099},
539	        "VIC", new int[] {3000, 3099},
540	        "QLD", new int[] {4000, 4099});
541	
542	    /**
543	     * Validates an owner's optional {@code postcode}. When absent nothing is checked (postcode is
544	     * optional, so the request contract stays backward-compatible). When present it must be exactly
545	     * four digits and, for a city whose region is known, fall within that region's inclusive range
546	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); a city with no known region accepts any 4-digit
547	     * postcode. A malformed or out-of-range value is rejected with a 400.
548	     *
549	     * @param postcode the raw postcode from the request (may be {@code null} when not supplied)
550	     * @param city the owner's city, used to look up the region whose range constrains the postcode
551	     * @throws InvalidFieldValueException if the postcode is present but malformed or out of range
552	     */
553	    private void validatePostcode(String postcode, String city) {
554	        if (postcode == null) {
555	            return;
556	        }
557	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
558	            throw new InvalidFieldValueException("postcode", "Postcode must be exactly four digits");
559	        }
560	        String region = OwnerMapper.CITY_REGION.getOrDefault(city, "UNKNOWN");
561	        int[] range = REGION_POSTCODES.get(region);
562	        if (range == null) {
563	            return;
564	        }
565	        int value = Integer.parseInt(postcode);
566	        if (value < range[0] || value > range[1]) {
567	            throw new InvalidFieldValueException("postcode",
568	                "Postcode must be valid for the city's region " + region);
569	        }
570	    }
571	
572	    /**
573	     * Validates an owner's optional {@code registrationDate}. When absent nothing is checked (the
574	     * date defaults to the server date). When present it must not be later than the current server
575	     * date: a registration cannot be recorded in the future, so a future date is rejected with a 400.
576	     *
577	     * @param registrationDate the supplied registration date (may be {@code null} when not supplied)
578	     * @throws InvalidFieldValueException if the supplied date is later than the server date
579	     */
580	    private void validateRegistrationDate(LocalDate registrationDate) {
581	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
582	            throw new InvalidFieldValueException("registrationDate",
583	                "Registration date must not be later than the current date");
584	        }
585	    }
586	
587	    private void requireCityBelowCapacity(String city) {
588	        long cityOwners = this.clinicService.findAllOwners().stream()
589	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
590	            .count();
591	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
592	            throw new CityAtCapacityException(city);
593	        }
594	    }
595	
596	    /**
597	     * Rejects the request when the incoming owner's derived {@code identityKey} exactly matches that
598	     * of any existing owner. The key ({@code normalizedTelephone + '|' + (email or empty) + '|' +
599	     * (householdId or empty)}) is the single consolidated duplicate-detection key that replaces the
600	     * former separate telephone, email and household checks. Because the telephone is part of the
601	     * key, two members of the same household (same {@code householdId}) with different telephones
602	     * have different keys and are both allowed; only an exact full-key match is a duplicate. The key
603	     * is derived identically for the incoming and existing owners via {@link OwnerMapper#toIdentityKey}.
604	     *
605	     * @param owner the incoming owner, with its normalized telephone, email and household identifier
606	     *              already populated
607	     * @throws DuplicateIdentityException if another owner already has this exact identity key
608	     */
609	    private void requireUniqueIdentity(Owner owner) {
610	        String identityKey = ownerMapper.toIdentityKey(owner);
611	        boolean taken = this.clinicService.findAllOwners().stream()
612	            .map(ownerMapper::toIdentityKey)
613	            .anyMatch(identityKey::equals);
614	        if (taken) {
615	            throw new DuplicateIdentityException(identityKey);
616	        }
617	    }
618	
619	    /**
620	     * Rejects the request when the incoming owner would join an existing household, unless the owner
621	     * has opted in via {@code sharesHousehold}. Because the household is keyed on {@code householdId}
622	     * (the computed hash of the normalized last name and postcode), any existing owner carrying the
623	     * same {@code householdId} is a member of the same household, so a second such owner is a
624	     * household duplicate. Setting {@code sharesHousehold} bypasses this block, declaring the owner a
625	     * genuine additional member of that household. An owner with no {@code householdId} (no postcode,
626	     * so no household key) is never a household duplicate.
627	     *
628	     * @param owner the incoming owner, with its computed {@code householdId} already populated
629	     * @param sharesHousehold whether the request opted in to joining an existing household
630	     * @throws DuplicateIdentityException if the household already exists and the owner did not opt in
631	     */
632	    private void requireNoHouseholdDuplicate(Owner owner, boolean sharesHousehold) {
633	        if (sharesHousehold) {
634	            return;
635	        }
636	        String householdId = owner.getHouseholdId();
637	        if (householdId == null) {
638	            return;
639	        }
640	        boolean householdExists = this.clinicService.findAllOwners().stream()
641	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
642	        if (householdExists) {
643	            throw new DuplicateIdentityException(ownerMapper.toIdentityKey(owner));
644	        }
645	    }
646	
647	    /**
648	     * Flags the incoming owner as a possible (soft) duplicate. Called after the hard-duplicate and
649	     * household-duplicate checks have passed, so the owner is known not to be a rejected duplicate.
650	     * When an existing owner shares this owner's household (same computed {@code householdId}) but
651	     * carries a different telephone, the owner is a possible duplicate: {@code possibleDuplicate} is
652	     * set {@code true} and {@code possibleDuplicateOf} to that existing owner's id (the earliest such
653	     * owner by id when more than one matches). Otherwise both are cleared. A declared household member
654	     * ({@code sharesHousehold} true) is never flagged: it is a deliberate member, not a suspected
655	     * duplicate. An owner with no {@code householdId} never matches, since it shares no household.
656	     *
657	     * @param owner the incoming owner, with its computed {@code householdId} and telephone populated
658	     * @param sharesHousehold whether the request opted in as a declared household member
659	     */
660	    private void markPossibleDuplicate(Owner owner, boolean sharesHousehold) {
661	        owner.setPossibleDuplicate(false);
662	        owner.setPossibleDuplicateOf(null);
663	        if (sharesHousehold) {
664	            return;
665	        }
666	        String householdId = owner.getHouseholdId();
667	        if (householdId == null) {
668	            return;
669	        }
670	        String telephone = owner.getTelephone();
671	        this.clinicService.findAllOwners().stream()
672	            .filter(existing -> householdId.equals(existing.getHouseholdId())
673	                && !java.util.Objects.equals(telephone, existing.getTelephone()))
674	            .min(java.util.Comparator.comparing(Owner::getId))
675	            .ifPresent(match -> {
676	                owner.setPossibleDuplicate(true);
677	                owner.setPossibleDuplicateOf(match.getId());
678	            });
679	    }
680	
681	    /**
682	     * Normalizes a value for household-duplicate comparison: trims leading and trailing whitespace,
683	     * collapses every internal run of whitespace to a single space, and lower-cases the result so
684	     * comparisons are case-insensitive.
685	     */
686	    private static String normalizeForHousehold(String value) {
687	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
688	    }
689	
690	    /**
691	     * Normalizes an owner's address to its canonical stored form: leading and trailing whitespace is
692	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
693	     * upper-cased, and common street-type abbreviations are expanded on a whole-word basis
694	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or whitespace-only
695	     * value normalizes to the empty string, so the required-field check rejects an address that is
696	     * blank once normalized. For example {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}.
697	     *
698	     * @param address the raw address value from the request (may be {@code null})
699	     * @return the normalized address, or the empty string when blank after normalization
700	     */
701	    private static String normalizeAddress(String address) {
702	        if (address == null) {
703	            return "";
704	        }
705	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
706	        if (collapsed.isEmpty()) {
707	            return "";
708	        }
709	        String[] tokens = collapsed.split(" ");
710	        StringBuilder sb = new StringBuilder();
711	        for (String token : tokens) {
712	            String expanded = switch (token) {
713	                case "ST" -> "STREET";
714	                case "RD" -> "ROAD";
715	                case "AVE" -> "AVENUE";
716	                default -> token;
717	            };
718	            if (sb.length() > 0) {
719	                sb.append(' ');
720	            }
721	            sb.append(expanded);
722	        }
723	        return sb.toString();
724	    }
725	
726	    /**
727	     * Derives the stable household identifier for an owner from its last name and postcode as the
728	     * upper-cased first 12 hex characters of the SHA-256 digest of
729	     * {@code normalizedLastName + '|' + postcode}, where the last name is normalized (trimmed,
730	     * internal whitespace collapsed, lower-cased) so casing and spacing do not affect it. Because the
731	     * identifier is a deterministic function of the normalized last name and postcode, owners that
732	     * share a last name and postcode share the identifier automatically — no back-fill or opt-in is
733	     * required. Returns {@code null} when no postcode is present, since the household is keyed on the
734	     * postcode and there is then nothing to key on.
735	     *
736	     * @param lastName the owner's last name (already validated non-blank)
737	     * @param postcode the owner's postcode (a validated 4-digit value, or {@code null} when absent)
738	     * @return the 12-hex-character household identifier, or {@code null} when no postcode is present
739	     */
740	    private static String householdIdFor(String lastName, String postcode) {
741	        if (postcode == null || postcode.isBlank()) {
742	            return null;
743	        }
744	        String normalizedLastName = normalizeForHousehold(lastName);
745	        try {
746	            byte[] digest = MessageDigest.getInstance("SHA-256")
747	                .digest((normalizedLastName + "|" + postcode).getBytes(StandardCharsets.UTF_8));
748	            StringBuilder sb = new StringBuilder();
749	            for (byte b : digest) {
750	                sb.append(String.format("%02X", b));
751	            }
752	            return sb.substring(0, 12);
753	        }
754	        catch (NoSuchAlgorithmException e) {
755	            throw new IllegalStateException("SHA-256 not available", e);
756	        }
757	    }
758	}
